<script setup lang="ts">
import { ArrowRight, BookOpenText, Boxes, FileText, FlaskConical } from 'lucide-vue-next'
import StatusDot from '@/components/ui/StatusDot.vue'
import AppBadge from '@/components/ui/AppBadge.vue'
import { paperStatusMeta } from '@/modules/papers/data'
import { useWorkspaceStore } from '@/stores/workspace'
import { useSiteContentStore } from '@/stores/siteContent'
import { computed } from 'vue'
import { storeToRefs } from 'pinia'
const workspace = useWorkspaceStore()
const siteContent = useSiteContentStore()
const { papers, servers } = storeToRefs(workspace)
const documents = computed(() => workspace.documents.filter(d => !d.trashedAt).sort((a,b) => b.updatedAt.localeCompare(a.updatedAt)))
const currentResearch = computed(() => siteContent.content.currentResearch)
const activeResearchCount = computed(() => currentResearch.value.filter(item => item.status.toLowerCase().includes('active')).length)
const onlineServerCount = computed(() => servers.value.filter(server => server.status !== 'offline').length)
const gpuCount = computed(() => servers.value.reduce((count, server) => count + server.gpus.length, 0))
const todayLabel = new Intl.DateTimeFormat('en-US', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date()).toUpperCase()
</script>
<template><div><header class="overview-greeting"><div><p>{{ todayLabel }}</p><h1>Good evening, Syins.</h1><span>Here’s the current state of your research workspace.</span></div><div class="overview-focus"><span><i /> Current focus</span><strong>{{ currentResearch[0]?.title || 'No current research set' }}</strong><RouterLink to="/dashboard/content">Edit public site <ArrowRight :size="13" /></RouterLink></div></header><section class="stat-row"><article><FlaskConical :size="18" /><div><span>Research</span><strong>{{ activeResearchCount }} <small>active</small></strong><p>{{ currentResearch.length }} tracked questions</p></div></article><article><BookOpenText :size="18" /><div><span>Recommended papers</span><strong>{{ papers.length }} <small>collected</small></strong><p>{{ papers.filter(p => p.status === 'to_read').length }} to read</p></div></article><article><Boxes :size="18" /><div><span>Servers</span><strong>{{ onlineServerCount }} / {{ servers.length }} <small>online</small></strong><p>{{ gpuCount }} GPUs</p></div></article><article><FileText :size="18" /><div><span>Documents</span><strong>{{ documents.length }} <small>total</small></strong><p>{{ documents.filter(d => d.visibility === 'private').length }} private</p></div></article></section><div class="overview-grid"><section class="overview-panel current-research-panel"><header><div><p>Research</p><h2>Current research</h2></div><RouterLink to="/dashboard/content">Manage <ArrowRight :size="14" /></RouterLink></header><div class="overview-research-list"><article v-for="item in currentResearch" :key="item.id"><div><h3>{{ item.title }}</h3><p>{{ item.status }} · {{ item.updated }}</p></div><span>{{ item.status }}</span></article><p v-if="!currentResearch.length" class="empty-hint">No current research questions yet.</p></div></section><section class="overview-panel server-status-panel"><header><div><p>Infrastructure</p><h2>Server status</h2></div><RouterLink to="/dashboard/servers">Fleet <ArrowRight :size="14" /></RouterLink></header><div class="compact-server-list"><article v-for="server in servers.slice(0,3)" :key="server.id"><StatusDot :status="server.status" /><div><h3>{{ server.name }}</h3><p>{{ server.status === 'offline' ? `Last seen ${server.lastSeen || 'never'}` : `${server.cpu}% CPU · ${server.memory.used} GB RAM` }}</p></div><span v-if="server.gpus.length && server.status !== 'offline'">{{ server.gpus[0].utilization }}% GPU</span><span v-else>{{ server.status }}</span></article><p v-if="!servers.length" class="empty-hint">No servers in the inventory.</p></div></section><section class="overview-panel recent-papers-panel"><header><div><p>Literature</p><h2>Recently recommended</h2></div><RouterLink to="/dashboard/papers">All papers <ArrowRight :size="14" /></RouterLink></header><div class="compact-paper-list"><article v-for="paper in papers.slice(0,4)" :key="paper.id"><AppBadge :tone="paperStatusMeta[paper.status].tone">{{ paperStatusMeta[paper.status].label }}</AppBadge><div><h3>{{ paper.title }}</h3><p>{{ paper.venue }} {{ paper.year }} · {{ paper.topic }}</p></div><time>{{ paper.recommendedAt.replace(', 2026','') }}</time></article><p v-if="!papers.length" class="empty-hint">No recommended papers yet.</p></div></section><section class="overview-panel recent-docs-panel"><header><div><p>Writing</p><h2>Recent documents</h2></div><RouterLink to="/dashboard/docs">All docs <ArrowRight :size="14" /></RouterLink></header><div class="compact-doc-list"><article v-for="doc in documents.slice(0, 3)" :key="doc.id"><FileText :size="16" /><div><h3><RouterLink :to="{ path: '/dashboard/docs', query: { note: doc.id } }">{{ doc.title }}</RouterLink></h3><p>{{ doc.updatedAt }} · {{ doc.visibility }}</p></div></article><p v-if="!documents.length">No active documents yet.</p></div></section></div></div></template>
